/**
 * Selbsttest der Übung. Bitte nicht verändern!
 * Starten: Klick auf das kleine Dreieck links neben "@Test" oder auf der Website "Tests starten".
 */
public class ParkhausTest {

   @Test
   public void leeresParkhausAmEnde() {
      Parkhaus p = new Parkhaus();
      Assertions.assertTrue(p.pruefe(""), "Das leere Protokoll: Das Parkhaus ist leer, also akzeptiert (Z0 ist Endzustand).");
      Assertions.assertTrue(p.pruefe("ea"), "ea: ein Auto rein, eines raus.");
      Assertions.assertTrue(p.pruefe("eeeaaa"), "eeeaaa: voll und wieder leer.");
      Assertions.assertTrue(p.pruefe("eaea"), "eaea: zweimal rein und raus.");
   }

   @Test
   public void nichtLeerAmEnde() {
      Parkhaus p = new Parkhaus();
      Assertions.assertFalse(p.pruefe("e"), "e: Ein Auto steht noch drin.");
      Assertions.assertFalse(p.pruefe("eeae"), "eeae: Am Ende stehen zwei Autos im Parkhaus.");
   }

   @Test
   public void ueberlaufUndUnterlauf() {
      Parkhaus p = new Parkhaus();
      Assertions.assertFalse(p.pruefe("a"), "a: Aus einem leeren Parkhaus kann kein Auto fahren (ZF).");
      Assertions.assertFalse(p.pruefe("eeeeaaaa"), "eeeeaaaa: Das vierte Auto passt nicht hinein (ZF), auch wenn danach vier ausfahren.");
      Assertions.assertFalse(p.pruefe("eaa"), "eaa: Unterlauf nach dem ersten Paar (ZF).");
      Assertions.assertFalse(p.pruefe("ex"), "ex: x ist kein Zeichen des Alphabets (ZF).");
   }
}
